let shard_number = match sharding_method.unwrap_or_default() {
    ShardingMethod::Auto => {
        if let Some(shard_number) = shard_number {
            shard_number  // DIRECT PASS-THROUGH, NO RANGE CHECK
        } else {
            collection_shard_distribution.shard_count() as u32
        }
    }
};

